"""IGMP and VRRP alone and inside IPv6, on dpkt's vectors and generated bytes."""

import importlib.util
import subprocess
import sys
import unittest
from pathlib import Path

import octetrail
from octetrail import NeedData, igmp, ip6, vrrp

ROOT = Path(__file__).resolve().parents[2]
SPEC = importlib.util.spec_from_file_location(
    "igmp_vrrp_fixture", ROOT / "tools/igmp_vrrp_differential.py"
)
F = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(F)
CASES = {k: bytes.fromhex(h) for k, (_, h) in F.cases().items()}


class IgmpVrrpTests(unittest.TestCase):
    def test_every_case_runs(self):
        report = F.exercise(octetrail)
        self.assertEqual(set(report["cases"]), set(CASES))
        for name in ("igmp_query", "vrrp_dpkt", "ip6_igmp", "ip6_vrrp"):
            self.assertNotIn("error", report["cases"][name], name)

    def test_igmp_fields_and_checksum(self):
        message = igmp.IGMP(CASES["igmp_report"])
        self.assertEqual(
            (message.type, message.group, message.data), (0x16, b"\xe0\0\0\xfb", b"tail")
        )
        self.assertEqual(bytes(igmp.IGMP()), b"\0\0\xff\xff" + bytes(4))
        self.assertEqual(bytes(igmp.IGMP(sum=1)), b"\0\0\0\1" + bytes(4))
        with self.assertRaises(NeedData):
            igmp.IGMP(CASES["igmp_short"])

    def test_vrrp_addresses_and_auth(self):
        message = vrrp.VRRP(CASES["vrrp_dpkt"])
        self.assertEqual((message.v, message.type, message.count), (2, 1, 1))
        self.assertEqual(message.addrs, [b"\xc0\xa8\x00\x01"])
        self.assertEqual((message.auth, message.data), (bytes(8), b""))
        self.assertEqual(bytes(message), CASES["vrrp_dpkt"])
        self.assertEqual(vrrp.VRRP(CASES["vrrp_zero_count"]).auth, b"skipauth")
        cut = vrrp.VRRP(CASES["vrrp_short_addrs"])
        self.assertEqual(cut.addrs, [b"\x0a\0\0\x01", b"\x0a\0", b""])
        built = vrrp.VRRP(count=1, addrs=[b"\x0a\0\0\x01"], auth=b"pw")
        self.assertEqual(len(bytes(built)), 14)
        self.assertNotEqual(built.sum, 0)

    def test_ipv6_decodes_both(self):
        self.assertIsInstance(ip6.IP6(CASES["ip6_igmp"]).data, igmp.IGMP)
        self.assertIsInstance(ip6.IP6(CASES["ip6_vrrp"]).data, vrrp.VRRP)
        self.assertEqual(ip6.IP6(CASES["ip6_igmp_short"]).data, b"\x11\x64")

    def test_long_address_list_is_linear(self):
        message = vrrp.VRRP(F.vrrp(255, bytes(4 * 255) + b"pw"))
        self.assertEqual((len(message.addrs), message.auth), (255, b"pw"))

    def test_optimized_probe_rejects_wrong_provider_version(self):
        result = subprocess.run(
            [
                sys.executable,
                "-B",
                "-I",
                "-O",
                ROOT / "tools/igmp_vrrp_differential.py",
                "--probe",
                "--module",
                "octetrail",
                "--version",
                "9.9.9",
            ],
            capture_output=True,
            text=True,
            check=False,
        )
        self.assertNotEqual(result.returncode, 0)
        self.assertIn("wrong provider version", result.stderr)


if __name__ == "__main__":
    unittest.main()
